package gobuf_test

import (
	"strings"
	"testing"

	"github.com/simonjanss/rig/internal/gen/gobuf"
)

func TestEmitsFormattedSource(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Doc("Package store is generated.")
	b.L("type Lesson struct {")
	b.L("ID %s.UUID", b.Import("github.com/google/uuid"))
	b.L("CreatedAt %s.Time", b.Import("time"))
	b.L("}")

	out, err := b.Bytes()
	if err != nil {
		t.Fatalf("emit: %v", err)
	}
	got := string(out)

	for _, want := range []string{
		"// Code generated by rig. DO NOT EDIT.",
		"// Package store is generated.",
		"package store",
		`"time"`,
		`"github.com/google/uuid"`,
		"\tID        uuid.UUID", // gofmt aligned the fields
	} {
		if !strings.Contains(got, want) {
			t.Errorf("missing %q:\n%s", want, got)
		}
	}
}

func TestStdlibImportsComeFirst(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Import("github.com/google/uuid")
	b.Import("time")
	b.Import("context")
	b.L("var _ = 1")

	out, _ := b.Bytes()
	got := string(out)

	stdEnd := strings.Index(got, `"time"`)
	thirdStart := strings.Index(got, `"github.com/google/uuid"`)
	if stdEnd < 0 || thirdStart < 0 || stdEnd > thirdStart {
		t.Errorf("standard library should come first:\n%s", got)
	}
}

func TestCollidingImportsAreAliased(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	first := b.Import("github.com/simonjanss/rig/runtime/query")
	second := b.Import("example.com/other/query")

	if first == second {
		t.Fatalf("both imports resolved to %q; one must be aliased", first)
	}

	b.L("var _ = %s.Op(\"\")", first)
	b.L("var _ = %s.Thing{}", second)
	out, err := b.Bytes()
	if err != nil {
		t.Fatalf("emit: %v", err)
	}
	if !strings.Contains(string(out), second+" ") {
		t.Errorf("the alias should appear in the import block:\n%s", out)
	}
}

func TestRepeatedImportReturnsTheSameName(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	if a, c := b.Import("time"), b.Import("time"); a != c {
		t.Errorf("Import is not stable: %q then %q", a, c)
	}
}

func TestCommentWraps(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Comment(strings.Repeat("word ", 40) + "\n\nA second paragraph.")
	b.L("var _ = 1")

	out, _ := b.Bytes()
	for _, line := range strings.Split(string(out), "\n") {
		if len(line) > 80 {
			t.Errorf("line is %d characters:\n%s", len(line), line)
		}
	}
	if !strings.Contains(string(out), "//\n") {
		t.Error("the paragraph break was lost")
	}
}

// A syntax error in emitted code otherwise surfaces as an opaque gofmt
// complaint about a file nobody can see.
func TestBrokenSourceReportsItself(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.L("type Lesson struct {")
	// no closing brace

	_, err := b.Bytes()
	if err == nil {
		t.Fatal("unparseable source should be an error")
	}
	if !strings.Contains(err.Error(), "type Lesson struct {") {
		t.Errorf("the error should show the source:\n%v", err)
	}
	if !strings.Contains(err.Error(), "|") {
		t.Errorf("the source should be line-numbered:\n%v", err)
	}
}
